package com.nigson.experience.lead;

import java.time.*;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.experience.consent.PhoneSecrets;
import com.nigson.experience.platform.*;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.CallbackSignatures;
import static org.assertj.core.api.Assertions.*;

class InboundMessagePersistenceTest {
    static final String ACCOUNT="AC0123456789abcdef0123456789abcdef", TOKEN="synthetic-twilio-auth-token-never-for-live";
    JdbcTemplate jdbc;InboundMessageProcessor processor;PhoneSecrets phones;InboundMessageSecrets secrets;String url;
    @BeforeEach void setup(){url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"messaging native harness supplies PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");jdbc=new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime"));var manager=new DataSourceTransactionManager(jdbc.getDataSource());var metrics=new SimpleMeterRegistry();var clock=Clock.systemUTC();byte[] h=new byte[32],p=new byte[32],k=new byte[32];Arrays.fill(h,(byte)4);Arrays.fill(p,(byte)5);Arrays.fill(k,(byte)6);phones=new PhoneSecrets(1,h,"local",Map.of("local",p));secrets=new InboundMessageSecrets(k);processor=new InboundMessageProcessor(jdbc,new AuditWriter(jdbc,clock,metrics),new PlatformStore(jdbc,manager,clock,metrics),phones,secrets,metrics,clock,manager,ACCOUNT,TOKEN,"whatsapp:+2348031234567","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp",30,"synthetic-sales-triage");}
    Map<String,String> form(String sid,String body){return Map.of("AccountSid",ACCOUNT,"MessageSid",sid,"From","whatsapp:+2348037654321","To","whatsapp:+2348031234567","Body",body);}
    String signature(Map<String,String> form)throws Exception{StringBuilder value=new StringBuilder("https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");new TreeMap<>(form).forEach((k,v)->value.append(k).append(v));Mac mac=Mac.getInstance("HmacSHA1");mac.init(new SecretKeySpec(TOKEN.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA1"));return Base64.getEncoder().encodeToString(mac.doFinal(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    String sid(){return "SM"+UUID.randomUUID().toString().replace("-","");}
    String accept(Map<String,String> form)throws Exception{return processor.accept(signature(form),form,UUID.randomUUID());}
    @Test void badSignatureDoesNotCreateInboundRecord()throws Exception{var f=form(sid(),"hello");assertThatThrownBy(()->processor.accept("invalid",f,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.inbound_message WHERE provider_message_id=?",Long.class,f.get("MessageSid"))).isZero();}
    @Test void helpIsFixedAndSidReplayMustMatchOriginalSenderAndBody()throws Exception{var f=form(sid(),"HELP");String response=accept(f);assertThat(response).contains("For assistance, contact Nigson support through official channels.");assertThat(accept(f)).isEqualTo(response);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.inbound_message WHERE provider_message_id=?",Long.class,f.get("MessageSid"))).isEqualTo(1);var changed=form(f.get("MessageSid"),"different");assertThatThrownBy(()->accept(changed)).isInstanceOf(PlatformStore.Conflict.class);}
    @Test void freeTextCreatesPrivateLeadAndOutboxWithoutPlaintextContactData()throws Exception{String secret="private inquiry "+UUID.randomUUID();var f=form(sid(),secret);assertThat(accept(f)).contains("<Response></Response>");UUID lead=jdbc.queryForObject("SELECT lead_id FROM experience.inbound_message WHERE provider_message_id=?",UUID.class,f.get("MessageSid"));assertThat(jdbc.queryForObject("SELECT email FROM experience.lead WHERE id=?",String.class,lead)).isNull();assertThat(jdbc.queryForObject("SELECT phone IS NULL AND message='Verified WhatsApp inquiry; see linked private inbound record.' FROM experience.lead WHERE id=?",Boolean.class,lead)).isTrue();byte[] cipher=jdbc.queryForObject("SELECT body_ciphertext FROM experience.inbound_message WHERE provider_message_id=?",byte[].class,f.get("MessageSid"));assertThat(new String(cipher,java.nio.charset.StandardCharsets.UTF_8)).doesNotContain(secret);assertThat(secrets.decrypt(jdbc.queryForObject("SELECT id FROM experience.inbound_message WHERE provider_message_id=?",UUID.class,f.get("MessageSid")),"BODY",cipher)).isEqualTo(secret);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='lead.created.v1' AND aggregate_id=?",Long.class,lead)).isEqualTo(1);}
    @Test void stopCommitsSuppressionAndConsentEventBeforeAcknowledgment()throws Exception{var f=form(sid()," stop ");accept(f);String hash=phones.fingerprint("+2348037654321");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.communication_suppression WHERE destination_hash=? AND channel='WHATSAPP' AND reason='OPT_OUT'",Long.class,hash)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='consent.changed.v1' AND aggregate_id=(SELECT id FROM experience.inbound_message WHERE provider_message_id=?)",Long.class,f.get("MessageSid"))).isEqualTo(1);}
    @Test void configuredRetentionErasesCiphertextAndKeepsReplayDeduplication()throws Exception{var f=form(sid(),"retention test");accept(f);UUID lead=jdbc.queryForObject("SELECT lead_id FROM experience.inbound_message WHERE provider_message_id=?",UUID.class,f.get("MessageSid"));jdbc.update("UPDATE experience.inbound_message SET retention_until=now()-interval '1 second' WHERE provider_message_id=?",f.get("MessageSid"));assertThat(processor.eraseExpired(100)).isGreaterThanOrEqualTo(1);assertThat(jdbc.queryForObject("SELECT sender_ciphertext IS NULL AND body_ciphertext IS NULL FROM experience.inbound_message WHERE provider_message_id=?",Boolean.class,f.get("MessageSid"))).isTrue();assertThat(accept(f)).contains("<Response></Response>");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.inbound_message WHERE provider_message_id=? AND lead_id=?",Long.class,f.get("MessageSid"),lead)).isEqualTo(1);}
}
